"""Freeze the lightweight evidence manifest last; never mutate finished reports."""
import gzip,hashlib,json,platform,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry as reg
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
rel=lambda p:str(p.relative_to(ROOT))
put=lambda p,x:p.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def main():
 assert not (R/'data_manifest.json').exists()
 start=json.loads((R/'startup.json').read_text());ctx=json.loads((R/'context.json').read_text());plan=json.loads((R/'plan.json').read_text());forward=json.loads((R/'forward_report.json').read_text());resume=json.loads((R/'forward_resume_plan.json').read_text());report=json.loads((R/'report.json').read_text());records=reg.read_records(ROOT/'research/automation/registry.jsonl');feed=json.loads((R/'feed_verification.json').read_text());assert feed['passed'];assert sha(R/'report.json')==feed['financial_report_sha256'] and sha(R/'forward_report.json')==feed['forward_report_sha256']
 receipts={name:json.loads((R/name).read_text()) for name in ['initial_commands.json','forward_commands.json','research_commands.json','gates_commands.json','feed_commands.json','review_commands.json']};receipts['source_check_receipt.json']=[json.loads((R/'source_check_receipt.json').read_text())]
 assert all(x['exit_code']==0 for rows in receipts.values() for x in rows)
 assert all(sha(ROOT/p)==h for p,h in ctx['account_hashes_before'].items())
 # The three partial observations and 54 financial configurations have final hashes.
 for row in json.loads((R/'batch.json').read_text())+json.loads((R/'forward_batch.json').read_text()):
  record=records[row['fingerprint']];partial=row['name'].startswith('forward_snapshot');assert record['result_available'] is True and record['report_sha256']==sha(R/('forward_report.json' if partial else 'report.json'))
 source_paths=set()
 for x in plan['component_sources'].values():source_paths.update([x['report'],x['archive'],x['spec']])
 old=json.loads((ROOT/plan['anchor_source']['report']).read_text())
 for ref in json.loads((R/'anchors.json').read_text()).values():source_paths.update([ref['report'],ref['archive'],old['configs'][ref['name']]['spec']])
 source_paths.update([plan['source_engine']['path'],'research/experiments/20261023T204326Z/run.py','research/experiments/20261023T204326Z/audit.py','research/experiments/20261023T204326Z/plan.json','research/experiments/20261023T003724Z/forward.py','research/experiments/20261023T003724Z/audit_forward.py','research/automation/registry.py','research/monitor/snapshot.py','checks/strategy_registry.py','checks/monitor_snapshot.py','AGENTS.md','research/automation/task.md','research/automation/README.md','research/monitor/README.md'])
 source_paths.update(f'.agents/skills/{s}/SKILL.md' for s in ['walk-forward-validation','ml4t-sensitivity-analysis','ml4t-transaction-costs'])
 source_paths.update(forward['source_hashes'])
 source_paths.update([resume['source_report'],resume['source_state'],resume['frozen_original_plan'],resume['daily_overlap_source']])
 previous=json.loads((ROOT/resume['source_report']).read_text());source_paths.add(previous['source_inputs_path'])
 hold=plan['read_only_hold_reference'];source_paths.update([hold['report'],hold['archive']])
 source_paths.update(p for p in ctx['ledger_fragments_before'] if p!='research/automation/registry.jsonl')
 sources={p:sha(ROOT/p) for p in sorted(source_paths)}
 for path,h in forward['source_hashes'].items():assert sources[path]==h
 for files in plan['data']['assets'].values():
  for info in files:assert sha(ROOT/info['path'])==info['sha256'] and (ROOT/info['path']).stat().st_size==info['bytes']
 intermediates=[p for p in R.rglob('*') if p.name=='__pycache__' or 'checkpoint' in p.name or p.suffix in ['.npy','.pyc','.tmp']];assert not intermediates
 cleanup={'verified_at_utc':datetime.now(timezone.utc).isoformat(),'rebuildable_intermediates_found':[],'removed':[],'reason':'No on-disk NPY/checkpoint/pycache or duplicate download pages generated. Only actual results,state,raw response audit evidence and reproducible code retained.','retained_original_raw_pages':len(forward['provenance']),'finished_report_original_bytes_preserved':True,'old_full_source_ledgers_only_referenced_not_copied':18,'large_market_data_remains_in_ignored_data':True,'preexisting_untracked_data_normalized_preserved':True};put(R/'cleanup.json',cleanup)
 with (R/'result.md').open('a') as f:f.write(f"\n最终登记与监控核验：57项均finish、114条只追加事件；strategy_registry和monitor_snapshot真正执行exit0，监控{feed['research_configs']}配置/{feed['paper_observations']}观察/{feed['paper_accounts']}账户。54新父组合/162场景及27旧父归属逐一校验，原4268受保护文件保持。必要结果、源状态连续性和失败事实完整保留；未生成可清理checkpoint/重复下载缓存。普通SSH非强推后的fetch/ls-remote/完整tree与证据字节终验回执留.git；完成后才释放本轮锁。\n")
 shared={p:{'sha256':sha(ROOT/p),'bytes':(ROOT/p).stat().st_size} for p in ['research/automation/registry.jsonl','research/monitor/latest.json','research/monitor/configs.json.gz']}
 source_results={fp:{'status':ref['original_status'],'report_sha256':ref['report_sha256']} for fp,ref in plan['component_sources'].items()}
 source_results.update({ref['fingerprint']:{'status':ref['original_status'],'report_sha256':ref['report_sha256']} for ref in json.loads((R/'anchors.json').read_text()).values()})
 source_results[hold['fingerprint']]={'status':hold['original_status'],'report_sha256':hold['report_sha256']}
 m={'round':R.name,'recorded_at_utc':datetime.now(timezone.utc).isoformat(),'working_directory':str(ROOT),'branch':'codex/strategy-research','base_commit':start['head_after_successful_SSH_fetch'],'branch_lock_broker_pid':start['branch_lock_broker_pid'],'frozen_plan_sha256':sha(R/'plan.json'),'finished_report_sha256':sha(R/'report.json'),'finished_forward_report_sha256':sha(R/'forward_report.json'),'frozen_original_SMA_plan':{'path':resume['frozen_original_plan'],'sha256':resume['frozen_original_plan_sha256']},'real_market_inputs':[x for files in plan['data']['assets'].values() for x in files],'large_market_data_policy':'8 original Parquets remain in ignored data; 18 complete source ledgers stay at original paths;54 new compact parent archives and complete original SMA9sceneNAV/state/raw response audit inputs retained;no format migration or changed finished bytes.','read_only_source_results':source_results,'code_and_frozen_source_sha256':sources,'protected_inputs_sha256':ctx['account_hashes_before'],'forward_source_continuity':resume,'forward_raw_responses':forward['provenance'],'forward_combined_inputs':{'path':rel(R/'forward_inputs.json.gz'),'sha256':sha(R/'forward_inputs.json.gz'),'bytes':(R/'forward_inputs.json.gz').stat().st_size},'registry':{'events_after':len(reg.read_events(ROOT/'research/automation/registry.jsonl')),'IDs_after':len(records),'new_finished_IDs':57,'new_financial_IDs':54,'new_partial_IDs':3,'main_append_only_events':114,'main_sha256_before_reserve':ctx['main_registry_sha256_before_reserve'],'main_sha256_after':shared['research/automation/registry.jsonl']['sha256'],'fragment_sha256_unchanged':{p:h for p,h in ctx['ledger_fragments_before'].items() if p!='research/automation/registry.jsonl'}},'history':{'initial16_missing_actual_results':0,'prior_events_read':ctx['registry_events'],'prior_IDs_read':ctx['registry_ids'],'prior_conclusions_read':len(ctx['prior_conclusions_read']),'prior_canonical_non_observation_definitions':ctx['canonical_research_definitions_excluding_observations'],'metadata_count_correction':ctx['canonical_count_correction'],'all_history_reused_development_evidence':True},'runtime':{'python':platform.python_version(),'executable':sys.executable,'numpy':__import__('numpy').__version__,'polars':__import__('polars').__version__,'matplotlib':__import__('matplotlib').__version__,'environment':{'PYTHONDONTWRITEBYTECODE':'1','OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1'}},'literature_sources':plan['sources'],'financial_verification':json.loads((R/'verification.json').read_text()),'forward_verification':json.loads((R/'forward_verification.json').read_text()),'monitor_validation':feed,'shared_files':shared,'monitor_source_commit_note':'Snapshot reflects base commit as it is generated before this commit. Feed content hashes and all result paths committed together.','cleanup':cleanup,'known_current_round_failures':json.loads((R/'read_failures.json').read_text()),'required_command_receipts':receipts,'all_final_required_gates_actual_exit0':True,'sensitivity_surface_actual_visual_inspection':True,'reproduce_workdir':str(ROOT),'reproduce_commands':[[sys.executable,rel(R/'audit.py')],[sys.executable,rel(R/'check_sources.py')],[sys.executable,rel(R/'forward.py'),'verify'],[sys.executable,rel(R/'audit_forward.py')],[sys.executable,rel(R/'check_feed.py')]],'reproduction_limit':'Use saved full source ledgers/actual data/raw responses;do not reserve/evaluate already finished fingerprints;new from-scratch research only in isolated audit environment with separate ledger.','publication_protocol':'Hold existing own broker through ordinary SSH push, fresh SSH fetch, independent ls-remote and full recursive tree/blob/data/result hash verification;release own broker only after actual passed proof in.git.'}
 m['artifacts']={rel(p):sha(p) for p in sorted(R.rglob('*')) if p.is_file() and p.name!='data_manifest.json'}
 put(R/'data_manifest.json',m)
 print(json.dumps({'manifest':rel(R/'data_manifest.json'),'artifacts':len(m['artifacts']),'total_round_bytes':sum(p.stat().st_size for p in R.rglob('*') if p.is_file()),'protected_files':len(m['protected_inputs_sha256']),'code_and_frozen_source_blobs':len(sources),'final_required_gates_actual_exit0':True,'report_sha256':m['finished_report_sha256'],'forward_report_sha256':m['finished_forward_report_sha256']}),flush=True)
if __name__=='__main__':main()
